 function setup() {
	randomSeed(seed);
	mySize = max(windowWidth, windowHeight);
  createCanvas(windowWidth, windowHeight,WEBGL);
	 colorbg = random(colors0);
  background(colorbg);
  t = rez = c = n = 0.01;
  color1 = random([colors3,colors4,colors5,colors6,colors7]);
	color2 = random([colors3,colors4,colors5,colors6,colors7]);
  // pixelDensity(5);
  xOff = 0;
  yOff = 0;
  zOff = 0;
}

function draw() {
		// orbitControl();
	randomSeed(seed);
  background(colorbg);

  translate(-width/2, -height/2);
	let plus = 15;
  for (let i = xOff; i < width - xOff; i += plus) {
    for (let j = yOff; j < height - yOff; j += plus) {
			strokeWeight(random(1));
      // strokeCap(SQUARE);
      var n = noise(i * rez+t, j * rez+t ,frameCount* 0.01+t);
      if (n > 0.5) {
				stroke(random(colors1));
        fill(random(color1));
      } else {
				noFill();
        stroke(random(color2));
      }

			push();
			translate(i, j);
      if (n > 0.45) {
        box(plus,plus,50*n);
      } else {
        box(plus*0.25*n);
      }
			pop();
    }
  }
  t += 0.01;
	zOff ++;
  // noLoop();
}



 function keyTyped() {
